insert into public.products (id, name, cat, price, tags, img, description, note, notes, variants, options, sort_order) values
  ('barako-brusko', 'Barako Brusko', 'coffee', 79, array['Hot']::text[], null, 'Our boldest cup: Batangas Liberica brewed strong and served black, the way it has been poured in Lipa for generations. Big body, low acidity, and a smoky finish that wakes you right up.', null, '[["Dark chocolate","tinta"],["Jackfruit","kalamansi"],["Smoke","banga"]]'::jsonb, null, '[{"key":"size","label":"Size","choices":[{"label":"12 oz"},{"label":"16 oz","add":20}]},{"key":"milk","label":"Milk","choices":[{"label":"As served"},{"label":"Oat","add":20},{"label":"Coconut","add":20}]},{"key":"sweet","label":"Sweetness","choices":[{"label":"Regular"},{"label":"Less sweet"},{"label":"No sugar"}]}]'::jsonb, 0),
  ('kape-kastila', 'Kape Kastila', 'coffee', 109, array['Iced']::text[], null, 'A Spanish-style latte: espresso, milk, and a ribbon of condensed milk, shaken hard over ice. Creamy, sweet, and dangerously easy to finish.', null, '[["Condensed milk","kalamansi"],["Toasted caramel","banga"],["Cocoa","tinta"]]'::jsonb, null, '[{"key":"size","label":"Size","choices":[{"label":"12 oz"},{"label":"16 oz","add":20}]},{"key":"milk","label":"Milk","choices":[{"label":"As served"},{"label":"Oat","add":20},{"label":"Coconut","add":20}]},{"key":"sweet","label":"Sweetness","choices":[{"label":"Regular"},{"label":"Less sweet"},{"label":"No sugar"}]}]'::jsonb, 1),
  ('ube-ulap-latte', 'Ube Ulap Latte', 'coffee', 119, array['Iced', 'Best Seller']::text[], 'ube-latte.jpg', 'Purple yam jam swirled into cold milk, topped with a shot of espresso and a soft cloud of ube cold foam. Our most photographed drink, and for good reason.', null, '[["Purple yam","ube"],["Vanilla","kalamansi"],["Espresso","tinta"]]'::jsonb, null, '[{"key":"size","label":"Size","choices":[{"label":"12 oz"},{"label":"16 oz","add":20}]},{"key":"milk","label":"Milk","choices":[{"label":"As served"},{"label":"Oat","add":20},{"label":"Coconut","add":20}]},{"key":"sweet","label":"Sweetness","choices":[{"label":"Regular"},{"label":"Less sweet"},{"label":"No sugar"}]}]'::jsonb, 2),
  ('batirol-mocha', 'Batirol Mocha', 'coffee', 119, array['Hot']::text[], null, 'Tablea chocolate whisked the old way with a wooden batirol, then poured over a double shot. Thick, bittersweet, and warm to the bone.', null, '[["Tablea cacao","tinta"],["Brown sugar","banga"],["Cinnamon","sili"]]'::jsonb, null, '[{"key":"size","label":"Size","choices":[{"label":"12 oz"},{"label":"16 oz","add":20}]},{"key":"milk","label":"Milk","choices":[{"label":"As served"},{"label":"Oat","add":20},{"label":"Coconut","add":20}]},{"key":"sweet","label":"Sweetness","choices":[{"label":"Regular"},{"label":"Less sweet"},{"label":"No sugar"}]}]'::jsonb, 3),
  ('niyog-affogato-salo-salo', 'Niyog Affogato Salo-Salo', 'coffee', 129, array['Seasonal']::text[], 'coconut-affogato.jpg', 'A scoop of toasted coconut ice cream drowned in a hot shot of espresso and finished with coconut caramel. Two spoons come with it, because it is meant for sharing.', null, '[["Toasted coconut","kalamansi"],["Caramel","banga"],["Espresso","tinta"]]'::jsonb, null, '[{"key":"scoop","label":"Scoop","choices":[{"label":"Single"},{"label":"Double","add":40}]}]'::jsonb, 4),
  ('arnibal-gold-slush', 'Arnibal Gold Slush', 'coolers', 49, array['Iced']::text[], null, 'Shaved ice, brown-sugar arnibal syrup, and a splash of fresh milk, blended into a golden slush. The sweetest ₱49 on Padre Faura.', null, '[["Brown sugar","banga"],["Molasses","tinta"],["Sweet cream","kalamansi"]]'::jsonb, null, '[{"key":"size","label":"Size","choices":[{"label":"12 oz"},{"label":"16 oz","add":20}]},{"key":"sweet","label":"Sweetness","choices":[{"label":"Regular"},{"label":"Less sweet"}]},{"key":"ice","label":"Ice","choices":[{"label":"Regular ice"},{"label":"Light ice"}]}]'::jsonb, 5),
  ('kalamansi-tanglad-fizz', 'Kalamansi Tanglad Fizz', 'coolers', 69, array['Iced', 'Best Seller']::text[], 'kalamansi-fizz.jpg', 'Freshly squeezed kalamansi and house lemongrass syrup, topped with sparkling water and a sprig of mint. Bright, tart, and built for Manila afternoons.', null, '[["Kalamansi","kalamansi"],["Lemongrass","jeepney"],["Mint","jeepney"]]'::jsonb, null, '[{"key":"size","label":"Size","choices":[{"label":"12 oz"},{"label":"16 oz","add":20}]},{"key":"sweet","label":"Sweetness","choices":[{"label":"Regular"},{"label":"Less sweet"}]},{"key":"ice","label":"Ice","choices":[{"label":"Regular ice"},{"label":"Light ice"}]}]'::jsonb, 6),
  ('melon-mestiza-chill', 'Melon Mestiza Chill', 'coolers', 89, array['Iced']::text[], 'melon-smoothie.jpg', 'Ripe cantaloupe blended with milk and ice: a creamy, grown-up take on the melon drink sold outside every school gate.', null, '[["Cantaloupe","kalamansi"],["Fresh milk","jeepney"],["Honey","banga"]]'::jsonb, null, '[{"key":"size","label":"Size","choices":[{"label":"12 oz"},{"label":"16 oz","add":20}]},{"key":"sweet","label":"Sweetness","choices":[{"label":"Regular"},{"label":"Less sweet"}]},{"key":"ice","label":"Ice","choices":[{"label":"Regular ice"},{"label":"Light ice"}]}]'::jsonb, 7),
  ('pandan-buko-frost', 'Pandan Buko Frost', 'coolers', 99, array['Iced', 'Seasonal']::text[], 'pandan-smoothie.jpg', 'Pandan-infused young coconut blended with coconut milk and ice, finished with whipped cream. Cool, fragrant, and just sweet enough.', null, '[["Pandan","jeepney"],["Young coconut","kalamansi"],["Vanilla","banga"]]'::jsonb, null, '[{"key":"size","label":"Size","choices":[{"label":"12 oz"},{"label":"16 oz","add":20}]},{"key":"sweet","label":"Sweetness","choices":[{"label":"Regular"},{"label":"Less sweet"}]},{"key":"ice","label":"Ice","choices":[{"label":"Regular ice"},{"label":"Light ice"}]}]'::jsonb, 8),
  ('halo-halo-ulap-frappe', 'Halo-Halo Ulap Frappe', 'coolers', 129, array['Iced', 'Seasonal']::text[], null, 'All the halo-halo favorites in one frappe: purple yam, leche flan, sweet beans, and toasted pinipig under a cloud of cream.', null, '[["Purple yam","ube"],["Leche flan","kalamansi"],["Toasted rice","banga"]]'::jsonb, null, '[{"key":"size","label":"Size","choices":[{"label":"12 oz"},{"label":"16 oz","add":20}]},{"key":"sweet","label":"Sweetness","choices":[{"label":"Regular"},{"label":"Less sweet"}]},{"key":"ice","label":"Ice","choices":[{"label":"Regular ice"},{"label":"Light ice"}]}]'::jsonb, 9),
  ('kutsinta', 'Kutsinta', 'pastries', 49, array['Rice Cake']::text[], null, 'Chewy steamed rice cakes made with brown sugar, served with a generous heap of freshly grated coconut.', null, '[["Brown sugar","banga"],["Grated coconut","kalamansi"]]'::jsonb, null, '[{"key":"pack","label":"Pack","choices":[{"label":"Single"},{"label":"Box of 4","mult":4},{"label":"Box of 6","mult":6}]},{"key":"serve","label":"Serve","choices":[{"label":"As is"},{"label":"Warmed"}]}]'::jsonb, 10),
  ('pan-kastila-roll', 'Pan Kastila Roll', 'pastries', 49, array['Pastry']::text[], null, 'Soft milk bread rolled around a buttery brown-sugar filling. Best warmed up and dunked straight into your coffee.', null, '[["Butter","kalamansi"],["Brown sugar","banga"]]'::jsonb, null, '[{"key":"pack","label":"Pack","choices":[{"label":"Single"},{"label":"Box of 4","mult":4},{"label":"Box of 6","mult":6}]},{"key":"serve","label":"Serve","choices":[{"label":"As is"},{"label":"Warmed"}]}]'::jsonb, 11),
  ('coco-pillow-bun', 'Coco Pillow Bun', 'pastries', 55, array['Pastry']::text[], null, 'A pillowy milk bun stuffed with sweet shredded coconut and topped with toasted sesame seeds.', null, '[["Sweet coconut","kalamansi"],["Toasted sesame","tinta"],["Milk bread","banga"]]'::jsonb, null, '[{"key":"pack","label":"Pack","choices":[{"label":"Single"},{"label":"Box of 4","mult":4},{"label":"Box of 6","mult":6}]},{"key":"serve","label":"Serve","choices":[{"label":"As is"},{"label":"Warmed"}]}]'::jsonb, 12),
  ('suman-sa-lihiya', 'Suman sa Lihiya', 'pastries', 59, array['Rice Cake']::text[], 'suman.jpg', 'Glutinous rice wrapped in banana leaves and slow-boiled until tender, served with coconut caramel for dipping.', null, '[["Banana leaf","jeepney"],["Coconut caramel","banga"]]'::jsonb, null, '[{"key":"pack","label":"Pack","choices":[{"label":"Single"},{"label":"Box of 4","mult":4},{"label":"Box of 6","mult":6}]},{"key":"serve","label":"Serve","choices":[{"label":"As is"},{"label":"Warmed"}]}]'::jsonb, 13),
  ('espasol', 'Espasol', 'pastries', 59, array['Rice Cake']::text[], 'espasol.jpg', 'Soft rice-flour rolls cooked low and slow in coconut milk, then dusted in toasted rice flour. A Laguna classic.', null, '[["Toasted rice","banga"],["Coconut milk","kalamansi"]]'::jsonb, null, '[{"key":"pack","label":"Pack","choices":[{"label":"Single"},{"label":"Box of 4","mult":4},{"label":"Box of 6","mult":6}]},{"key":"serve","label":"Serve","choices":[{"label":"As is"},{"label":"Warmed"}]}]'::jsonb, 14),
  ('turon-crisp', 'Turon Crisp', 'pastries', 69, array['Pastry']::text[], null, 'Saba banana and ripe jackfruit wrapped in a thin spring-roll wrapper, fried crisp, and glazed in burnt caramel.', null, '[["Saba banana","kalamansi"],["Jackfruit","kalamansi"],["Caramel","banga"]]'::jsonb, null, '[{"key":"pack","label":"Pack","choices":[{"label":"Single"},{"label":"Box of 4","mult":4},{"label":"Box of 6","mult":6}]},{"key":"serve","label":"Serve","choices":[{"label":"As is"},{"label":"Warmed"}]}]'::jsonb, 15),
  ('ensaymada-royale', 'Ensaymada Royale', 'pastries', 79, array['Pastry', 'Best Seller']::text[], 'ensaymada.jpg', 'Brioche-soft coils brushed with butter, dusted with sugar, and buried under grated aged cheese. The ube version hides a layer of purple yam jam inside.', null, '[["Butter","kalamansi"],["Aged cheese","banga"],["Purple yam","ube"]]'::jsonb, '[{"label":"Classic","price":79},{"label":"Ube","price":89}]'::jsonb, '[{"key":"flavor","label":"Flavor","choices":[{"label":"Classic","add":0},{"label":"Ube","add":10}]},{"key":"pack","label":"Pack","choices":[{"label":"Single"},{"label":"Box of 4","mult":4},{"label":"Box of 6","mult":6}]},{"key":"serve","label":"Serve","choices":[{"label":"As is"},{"label":"Warmed"}]}]'::jsonb, 16),
  ('tablea-pinipig-brownie', 'Tablea Pinipig Brownie', 'pastries', 99, array['Pastry']::text[], null, 'A dense, fudgy brownie made with Batangas tablea chocolate and topped with crispy toasted pinipig.', null, '[["Dark chocolate","tinta"],["Toasted rice","banga"]]'::jsonb, null, '[{"key":"pack","label":"Pack","choices":[{"label":"Single"},{"label":"Box of 4","mult":4},{"label":"Box of 6","mult":6}]},{"key":"serve","label":"Serve","choices":[{"label":"As is"},{"label":"Warmed"}]}]'::jsonb, 17),
  ('bibingka-basque-cheesecake', 'Bibingka Basque Cheesecake', 'pastries', 189, array['Seasonal', 'Best Seller']::text[], 'bibingka-basque.jpg', 'Our holiday mash-up: a burnt Basque cheesecake baked in a banana-leaf lining with salted egg and coconut, the way bibingka is.', 'Per slice', '[["Burnt caramel","banga"],["Salted egg","kalamansi"],["Banana leaf","jeepney"]]'::jsonb, null, '[{"key":"pack","label":"Size","choices":[{"label":"Slice"},{"label":"Whole cake (8 slices)","mult":8}]}]'::jsonb, 18);

